"""Linguistics-Fragen, Oberthema 1 (Dichotomies). Englisch = Klausursprache, deutsche Hilfe in de_hint.
Arbeitsblatt-Stil: Richtig/Falsch mit Korrektur (blk + rv), viele Lückentexte (lu)."""
from fr_basis import *

R, F = True, False

# ================================================================ dichotomies
fam('dichotomies', 'def', 'Knows what a dichotomy is',
    mc('In linguistics, a dichotomy is …', 'a pair of opposite but complementary perspectives', ['a mistake that two linguists disagree about', 'a rule that is true in only some languages', 'a single word that has exactly two different meanings'], 'Two sides, one object. · Zwei Seiten, ein Gegenstand.', 1, de='In der Sprachwissenschaft ist eine Dichotomie …'),
    lu('A dichotomy cuts a topic into [[0]] parts. The two sides are not right and wrong, but two different [[1]] on the same object: language.', [['two', '2'], ['perspectives', 'perspective', 'views', 'ways of looking']], 'two – perspectives. · zwei – Blickwinkel.', 1, de='Eine Dichotomie teilt ein Thema in … Teile. Die Seiten sind zwei verschiedene … auf denselben Gegenstand.'),
    li('Name the three dichotomies of the worksheet.', [['synchronic/diachronic', 'synchronic diachronic', 'synchronic', 'diachronic'], ['form/function', 'form function', 'form', 'function'], ['applied/theoretical', 'applied', 'theoretical', 'not applied', 'applied/not applied']], 'synchronic/diachronic · form/function · applied/theoretical.', 1, True, de='Nenne die drei Dichotomien des Arbeitsblatts.'),
    zu('Which pair does the term belong to?', ['synchronic / diachronic', 'form / function', 'theoretical / applied'], [('snapshot of a language', 0), ('purpose of an utterance', 1), ('speech therapy', 2), ('language change', 0), ('sentence structure', 1), ('describing the system for its own sake', 2)], '', 1, de='Zu welchem Paar gehört der Begriff?'),
    blk('True or false?', [('The two sides of a dichotomy exclude each other – only one of them is correct.', F), ('Dichotomies help to look at language from two angles.', R), ('In a true/false task, a false statement needs a corrected answer.', R), ('Langue/parole is also a dichotomy.', R)], 'Both sides belong together. · Beide Seiten gehören zusammen.', 1, de='Richtig oder falsch?'),
    lu('In the exam, if a statement is [[0]], you tick b and write the [[1]] answer on the line.', [['false', 'wrong', 'incorrect'], ['correct', 'right', 'corrected']], '', 1, True, de='Ist eine Aussage …, kreuzt du b an und schreibst die … Antwort auf die Linie.'),
    rh('Put the steps for a “True or false → correct answer” task in order.', ['find the two key terms', 'recall the definition of each term', 'compare: does the statement match?', 'write a full correct sentence for both terms'], 'Terms – definitions – compare – correct both. · Begriffe – Definitionen – vergleichen – beide korrigieren.', 2, de='Bringe die Schritte in die richtige Reihenfolge.'),
    kz('Complete: the Greek word “dicha” means “in …”.', ['two', 'zwei'], '', 1, de='Ergänze: das griechische „dicha“ heißt „in …“.'),
    mc('Which is NOT a dichotomy in linguistics?', 'phonology / morphology', ['langue / parole', 'competence / performance', 'descriptive / prescriptive'], 'Phonology and morphology are two disciplines, not two perspectives on the same object. · Zwei Disziplinen, keine zwei Blickwinkel.', 2, de='Was ist KEINE Dichotomie?'))

# ================================================================ synchronic / diachronic
fam('synchronic-diachronic', 'sd', 'Distinguishes synchronic and diachronic',
    blk('Worksheet 1.1 – true or false?', [('The term synchronic describes a specific point in time, while diachronic describes language change through time.', R)], 'TRUE – tick a, nothing to correct. · RICHTIG – a ankreuzen.', 2, True, de='Arbeitsblatt 1.1 – richtig oder falsch?'),
    lu('The term [[0]] describes a specific point in time, while [[1]] describes language change through time.', [['synchronic'], ['diachronic']], 'synchronic – diachronic.', 1, True, de='Der Begriff … beschreibt einen Zeitpunkt, … den Sprachwandel über die Zeit.'),
    lu('Synchronic linguistics studies language at one specific [[0]] in time, like a [[1]].', [['point', 'moment'], ['snapshot', 'photo', 'photograph', 'picture']], '', 1, de='Synchron: Sprache zu einem bestimmten … in der Zeit, wie eine ….'),
    lu('Diachronic (or [[0]]) linguistics studies how language [[1]] through time.', [['historical', 'historic'], ['changes', 'develops', 'evolves']], '', 2, de='Diachrone (oder …) Linguistik untersucht, wie Sprache sich über die Zeit ….'),
    lu('The prefix “syn” means [[0]], the prefix “dia” means [[1]]; “chronos” means [[2]].', [['together', 'same', 'with'], ['through', 'across'], ['time']], 'syn = together, dia = through, chronos = time.', 1, de='„syn“ heißt …, „dia“ heißt …, „chronos“ heißt ….'),
    zu('Synchronic or diachronic?', ['synchronic', 'diachronic'], [('the sound system of English today', 0), ('how “nice” changed from “foolish” to “pleasant”', 1), ('Old English grammar around the year 1000', 0), ('from “thou art” to “you are”', 1), ('slang of London teenagers in 2026', 0), ('the Great Vowel Shift', 1)], 'One moment = synchronic, change = diachronic. · Ein Moment = synchron, Wandel = diachron.', 2, True, de='Synchron oder diachron?'),
    mc('A linguist describes the grammar of Old English around the year 1000. This study is …', 'synchronic, because it looks at one point in time', ['diachronic, because Old English is an old language', 'diachronic, because the grammar has changed since', 'neither, because Old English is no longer spoken'], 'Old ≠ diachronic. · Alt ≠ diachron.', 3, de='Ein Linguist beschreibt die Grammatik des Altenglischen um 1000. Diese Studie ist …'),
    mc('Which question is diachronic?', 'How did the meaning of “girl” develop?', ['What does “girl” mean in English today?', 'How is “girl” pronounced in London today?', 'Which words rhyme with “girl” in English?'], '', 1, de='Welche Frage ist diachron?'),
    blk('True or false?', [('Synchronic means the same as “present-day”.', F), ('Saussure compared the synchronic view to the position on a chessboard.', R), ('Diachronic linguistics compares several stages of a language.', R), ('“Diachronic” means “at the same time”.', F)], '', 2, de='Richtig oder falsch?'),
    kz('Complete Saussure’s comparison: the current position on a chessboard corresponds to the … view.', ['synchronic', 'synchronic view'], '', 2, de='Die aktuelle Stellung auf dem Schachbrett entspricht der … Sicht.'),
    rv('Explain the difference between synchronic and diachronic linguistics with the word “nice”.', 'Synchronic: describe what “nice” means at one point in time, e.g. today “pleasant, kind”, or around 1300 “foolish”. Diachronic: describe how its meaning changed through time, from “foolish” (Middle English) via “precise” to “pleasant” today.', ['synchronic = one point in time (snapshot)', 'diachronic = change through time', 'nice: foolish → pleasant'], 2, de='Erkläre den Unterschied am Wort „nice“.'))

# ================================================================ form / function
fam('form-function', 'ff', 'Distinguishes form and function',
    blk('Worksheet 1.2 – true or false?', [('Function denotes a speaker’s ability to only be able to convey basic messages, while form denotes a mastery over the language.', F)], 'FALSE – tick b and correct it. · FALSCH – b ankreuzen und korrigieren.', 2, True, de='Arbeitsblatt 1.2 – richtig oder falsch?'),
    rv('Worksheet 1.2 is false. Write the correct answer.', 'Form refers to the structure of language – its sounds, word forms and sentence patterns (how something is said). Function refers to what a form is used for in communication – its purpose (e.g. a question used as a request).', ['form = structure of language (sounds, words, sentences)', 'function = purpose / use in communication', 'not about the speaker’s skill or mastery'], 2, True, de='Arbeitsblatt 1.2 ist falsch. Schreibe die richtige Antwort.'),
    lu('Correct answer 1.2: [[0]] refers to the structure of language, while [[1]] refers to what this structure is used for in communication.', [['form'], ['function']], '', 1, True, de='Richtige Antwort 1.2: … bezeichnet die Struktur, … wozu sie verwendet wird.'),
    lu('Form is the [[0]] of language: its sounds, word forms and sentence patterns. Function is its [[1]] in communication.', [['structure', 'shape'], ['purpose', 'use', 'job', 'role']], 'structure – purpose.', 1, True, de='Form ist die … der Sprache, Funktion ihr … in der Kommunikation.'),
    lu('“Can you open the window?” has the form of a [[0]], but its function is usually a [[1]].', [['question', 'interrogative', 'interrogative sentence', 'yes/no question', 'yes-no question'], ['request', 'polite request']], 'Form: question · function: request.', 2, True, de='„Can you open the window?“ hat die Form einer …, die Funktion ist meist eine ….'),
    zu('Form or function?', ['form', 'function'], [('the past tense ending -ed', 0), ('warning someone', 1), ('inverted word order in questions', 0), ('greeting a friend', 1), ('the sound /frɒg/', 0), ('complaining about the heat', 1)], 'Form = what it looks like, function = what it does.', 2, True, de='Form oder Funktion?'),
    mc('“It’s hot in here.” said to someone near the window. Which statement is correct?', 'its form is a statement, its function is a request', ['its form is a request, its function is a statement', 'its form and its function are both questions', 'it has a grammatical form but no communicative function'], '', 2, de='„It’s hot in here.“ zu jemandem am Fenster. Was stimmt?'),
    mc('What is wrong with worksheet statement 1.2?', 'it mixes up form and function with the speaker’s skill', ['form and function have been swapped by mistake', 'function describes the sounds of a language', 'form only exists in written texts, never in spoken language'], '', 2, True, de='Was ist an Aussage 1.2 falsch?'),
    blk('True or false?', [('One form can have several functions.', R), ('One function can be expressed by several forms.', R), ('Form describes how well someone masters a language.', F), ('Every question is used to ask for information.', F)], '', 2, de='Richtig oder falsch?'),
    li('Give three different forms that can all function as a request to open the window.', [['open the window', 'imperative'], ['can you', 'could you', 'would you', 'question'], ['it is hot', "it's hot", 'statement', 'declarative']], 'imperative · question · statement.', 3, de='Nenne drei Formen, die alle als Bitte funktionieren.'),
    kz('Complete: form answers the question “how?”, function answers the question “what …?”.', ['for', 'what for'], '', 1, de='Form: „wie?“, Funktion: „wozu?“ (englisch: what …?)'))

# ================================================================ applied / theoretical
fam('applied-theoretical', 'at', 'Distinguishes applied and theoretical linguistics',
    blk('Worksheet 1.3 – true or false?', [('Applied linguistics refers to studies that still have real-life applications, ‘not applied’ refers to studies in the past that are not in use anymore.', F)], 'FALSE – it is about the goal, not about time. · FALSCH – es geht ums Ziel, nicht um die Zeit.', 2, True, de='Arbeitsblatt 1.3 – richtig oder falsch?'),
    rv('Worksheet 1.3 is false. Write the correct answer.', 'Applied linguistics uses the findings of linguistics to solve practical, real-life problems, e.g. language teaching, translation or speech therapy. “Not applied” (theoretical) linguistics studies language for its own sake to describe and explain how it works. It is not about old studies.', ['applied = uses findings to solve real-life problems', 'example: teaching, translation, speech therapy', 'not applied = theoretical, studies language for its own sake', 'not about past vs. present'], 2, True, de='Aussage 1.3 ist falsch. Schreibe die richtige Antwort.'),
    lu('Applied linguistics uses linguistic findings to solve [[0]] problems. “Not applied” or [[1]] linguistics studies language for its own [[2]].', [['practical', 'real-life', 'real life', 'everyday'], ['theoretical', 'general', 'pure'], ['sake']], 'practical – theoretical – sake.', 2, True, de='Angewandte Linguistik löst … Probleme. „Nicht angewandte“ oder … Linguistik erforscht Sprache um ihrer selbst ….'),
    lu('Theoretical linguistics wants to [[0]] and [[1]] how the language system works.', [['describe'], ['explain']], '', 2, de='Theoretische Linguistik will … und …, wie das Sprachsystem funktioniert.'),
    zu('Applied or theoretical?', ['applied', 'theoretical'], [('a method to teach the English “th”', 0), ('describing English word order', 1), ('helping a child who cannot pronounce /r/', 0), ('a theory of how sentences are built', 1), ('finding the author of an anonymous letter', 0), ('describing the sound system of English', 1)], '', 2, True, de='Angewandt oder theoretisch?'),
    li('Name three fields of applied linguistics.', [['language teaching', 'teaching', 'foreign language teaching'], ['translation', 'translating', 'interpreting'], ['speech therapy', 'therapy'], ['forensic linguistics', 'forensic'], ['lexicography', 'dictionaries', 'dictionary']], '', 1, n=3, de='Nenne drei Bereiche der angewandten Linguistik.'),
    mc('What is the real difference between applied and theoretical linguistics?', 'the goal: solving practical problems vs. understanding language', ['the time: current studies vs. studies from the past', 'the language: English vs. other languages', 'the method: listening to speakers vs. reading written texts'], '', 2, True, de='Was ist der eigentliche Unterschied?'),
    mc('A researcher develops a theory of how English questions are formed. This is …', 'theoretical linguistics', ['applied linguistics', 'speech therapy', 'forensic linguistics and lexicography'], '', 1, de='Eine Forscherin entwickelt eine Theorie zur Bildung englischer Fragen. Das ist …'),
    blk('True or false?', [('Theoretical linguistics only studies old texts.', F), ('Translation is a field of applied linguistics.', R), ('Applied linguistics builds on the results of theoretical linguistics.', R), ('“Not applied” linguistics is no longer in use.', F)], '', 1, de='Richtig oder falsch?'),
    kz('Complete: speech therapy, translation and language teaching are fields of … linguistics.', ['applied'], '', 1, de='Sprachtherapie, Übersetzen und Sprachunterricht gehören zur … Linguistik.'))
